function sanitize_summary(...args: any[]) {
  let [html_summary] = args.slice(0);
  let [dom] = perlCompat.parseHtml(html_summary);
  dom.find('script').each((...args: any[]) => {args.shift().remove;});
  let summary = dom .toString();
  return summary;
}

function get_summary_from_dto(...args: any[]) {
  let [dto] = args.slice(0);
  let summary = dto["illustComment"];
  summary = perlCompat.htmlUnescape(summary);
  //# summary is html escaped by default and requires unescape to render.
  summary = sanitize_summary(summary);
  return summary;
}

function get_hash_metadata_from_json(...args: any[]) {
  let [json, illust_id, tag_languages_str] = args.slice(0);
  let logger = perlCompat.getLogger("Pixiv", "plugins");
  let hashdata = {} as Record<string, any>;
  //    # get illustration metadata.

  let illust_dto = get_illustration_dto_from_json(json, illust_id);
  let lrr_tags = [] as any[];
  let manga_data = get_manga_data_from_dto(illust_dto);
  let pixiv_tags = get_pixiv_tags_from_dto(illust_dto, tag_languages_str);
  lrr_tags.push(manga_data);
  lrr_tags.push(pixiv_tags);
  //    # add source

  let source = `https://pixiv.net/artworks/${illust_id}`;
  lrr_tags.push(`source:${source}`);
  //    # add general metadata.

  let user_id_data = get_user_id_from_dto(illust_dto);
  let user_name_data = get_artist_from_dto(illust_dto);
  lrr_tags.push(user_id_data);
  lrr_tags.push(user_name_data);
  //    # add time-based metadata.

  let create_date_epoch_data = get_create_date_from_dto(illust_dto);
  let upload_date_epoch_data = get_upload_date_from_dto(illust_dto);
  lrr_tags.push(create_date_epoch_data);
  lrr_tags.push(upload_date_epoch_data);
  hashdata["tags"] = lrr_tags.join(', ');
  //    # change title.

  let illust_title = illust_dto["illustTitle"];
  if ((illust_title !== undefined && illust_title !== null)) {
    illust_title = sanitize(illust_title);
    hashdata["title"] = illust_title;
  } else {
    logger.error("Failed to extract illustration title from json file: " + Dumper(json));
  }
  //    # add summary.

  let summary = get_summary_from_dto(illust_dto);
  if ((summary !== undefined && summary !== null)) {
    hashdata["summary"] = summary;
  }
  return hashdata;
}

function get_json_from_html(...args: any[]) {
  let [html] = args.slice(0);
  let logger = perlCompat.getLogger("Pixiv", "plugins");
  //    # get 'content' body.

  let dom = perlCompat.parseHtml(html);
  let jsonstring = dom.at('meta#meta-preload-data').attr('content');
  logger.debug(`Tentative JSON: ${jsonstring}`);
  let json = JSON.parse(jsonstring);
  return json;
}

async function get_json_from_ajax(...args: any[]) {
  let [illust_id, ua] = args.slice(0);
  let logger = perlCompat.getLogger("Pixiv", "plugins");
  let ajax_url = `https://www.pixiv.net/ajax/illust/${illust_id}`;
  logger.debug(`Attempting to fetch JSON from AJAX endpoint: ${ajax_url}`);
  let res = (await ua.get(ajax_url, {Referer: "https://www.pixiv.net"})).result;
  if (res.is_error) {
    let code = res.code;
    logger.debug(`Failed to fetch from AJAX endpoint: error (${code})`);
    return;
  }
  let content = res.body;
  logger.debug("AJAX response received, processing JSON");
  let json = undefined;
  let perlError;
  try {
    json = JSON.parse(content);
  } catch (caughtError) {
    perlError = caughtError;
  }
  if (perlError) {
    logger.error(`Failed to decode JSON from AJAX response: $@`);
    return;
  }
  if (json["error"]) {
    logger.error("Pixiv AJAX API returned an error: " + json["message"]);
    return;
  }
  let formatted_json = format_ajax_json(json, illust_id);
  return formatted_json;
}

function format_ajax_json(...args: any[]) {
  let [ajax_json, illust_id] = args.slice(0);
  let logger = perlCompat.getLogger("Pixiv", "plugins");
  let body = ajax_json["body"];
  if (! (body !== undefined && body !== null)) {
    logger.error("Unexpected AJAX response format, missing 'body' key");
    return;
  }
  let formatted_json = {illust: {$illust_id: {illustId: body["illustId"], illustTitle: body["title"], userId: body["userId"], userName: body["userName"], illustComment: body["description"], createDate: body["createDate"], uploadDate: body["uploadDate"], tags: {tags: body["tags"]["tags"]}}}};
  if ((body["seriesNavData"] !== undefined) && (body !== undefined && body !== null)["seriesNavData"]) {
    formatted_json["illust"][illust_id]["seriesNavData"] = body["seriesNavData"];
  }
  return formatted_json;
}

async function get_html_from_illust_id(...args: any[]) {
  let [illust_id, ua] = args.slice(0);
  let logger = perlCompat.getLogger("Pixiv", "plugins");
  //    # illustration ID to URL.

  let URL = `https://www.pixiv.net/en/artworks/${illust_id}/`;
  while (1) {
    let res = (await ua.get(URL, {Referer: "https://www.pixiv.net"})).result;
    let code = res.code;
    logger.debug(`Received code ${code}.`);
    //        # handle 3xx.
  
    if (code == 301) {
      URL = res.headers.location;
      logger.debug(`Redirecting to ${URL}`);
      continue;
    }
    if (code == 302) {
      let location = res.headers.location;
      URL = `pixiv.net${location}`;
      logger.debug(`Redirecting to ${URL}`);
      continue;
    }
    //        # handle 4xx.
  
    if (res.is_error) {
      let code = res.code;
      return `error (${code}) `;
    }
    //        # handle 2xx.
  
    return res.body;
  }
}

async function get_metadata_from_illust_id(...args: any[]) {
  let match: RegExpMatchArray | null;
  let [illust_id, ua, tag_languages_str] = args.slice(0);
  let logger = perlCompat.getLogger("Pixiv", "plugins");
  //    # initialize hash.

  let hashdata: Record<string, any> = { tags: "" };
  //    # Try nextjs ajax endpoint with server-side rendering fallback

  logger.debug(`Attempting to get metadata using Next.js AJAX endpoint for illustration ID: ${illust_id}`);
  let json = await get_json_from_ajax(illust_id, ua);
  if (! json) {
    logger.debug(`Next.js method failed, falling back to HTML parsing for illustration ID: ${illust_id}`);
    let html = await get_html_from_illust_id(illust_id, ua);
    if ((match = html.match(/^error/))) {
      throw new Error(`Error retrieving HTML from Pixiv Illustration: ${html}\n`);
    }
    json = get_json_from_html(html);
  }
  if (json) {
    hashdata = get_hash_metadata_from_json(json, illust_id, tag_languages_str);
  } else {
    logger.error(`Failed to retrieve metadata for illustration ID: ${illust_id}`);
  }
  return hashdata;
}
